package com.servora.knowledge;

/**
 * Private storage for uploaded documents. Objects are reachable only through the backend: there are
 * no public URLs, and keys are generated by the server, never taken from a filename.
 */
public interface DocumentStorage {

    void put(String key, byte[] content, String contentType);

    /** Removes the object. Removing a key that does not exist is not an error. */
    void delete(String key);
}
